from __future__ import annotations

import base64
import io
import tarfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
ARCHIVE_B64 = """"""

with tarfile.open(fileobj=io.BytesIO(base64.b64decode(ARCHIVE_B64)), mode="r:gz") as archive:
    for member in archive.getmembers():
        if not member.isfile() or member.name.startswith("/") or ".." in Path(member.name).parts:
            raise SystemExit(f"unsafe bootstrap member: {member.name}")
    archive.extractall(ROOT)

def insert_once(path: Path, marker: str, block: str, identity: str) -> None:
    text = path.read_text(encoding="utf-8")
    if identity in text:
        return
    if marker not in text:
        raise SystemExit(f"marker not found in {path}: {marker!r}")
    path.write_text(text.replace(marker, block + marker, 1), encoding="utf-8")

